<?php
$catalogKey = preg_replace('/[^a-zA-Z0-9_-]/', '', (string)($_GET['c'] ?? ''));
?><!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#101827"><title>Katalog</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#182230;background:#f5f7fa;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.top{background:#101827;color:#fff;padding:22px max(20px,calc((100% - 1120px)/2));display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-weight:750;font-size:19px}.live{font-size:13px;color:#b7f7d3}.wrap{max-width:1120px;margin:auto;padding:30px 20px}.intro h1{font-size:clamp(25px,5vw,38px);margin:4px 0}.intro p{color:#657184;margin:0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px;margin-top:26px}.card{background:#fff;border:1px solid #e7eaf0;border-radius:16px;overflow:hidden;box-shadow:0 3px 14px #18223008}.card img{width:100%;aspect-ratio:4/3;object-fit:cover;background:#edf0f4}.cardbody{padding:15px}.card h2{font-size:16px;margin:0 0 7px}.desc{font-size:13px;color:#657184;min-height:34px}.price{font-weight:750;margin:14px 0}.btn{border:0;border-radius:10px;padding:11px 14px;background:var(--accent,#2359d1);color:white;font-weight:650;cursor:pointer}.btn:disabled{opacity:.55}.card .btn{width:100%}.cart{position:fixed;right:20px;bottom:20px;background:#101827;color:#fff;border:0;border-radius:14px;padding:14px 18px;box-shadow:0 8px 30px #10182740;font-weight:700;cursor:pointer}.status{color:#657184;text-align:center;padding:60px 10px}.modal{position:fixed;inset:0;background:#10182788;display:none;align-items:flex-end;justify-content:center;padding:14px}.modal.open{display:flex}.sheet{background:#fff;border-radius:18px 18px 8px 8px;padding:22px;width:min(520px,100%);max-height:90vh;overflow:auto}.sheet h2{margin-top:0}.rows{display:grid;gap:10px;margin-bottom:20px}.row{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #eee;padding-bottom:8px}.field{display:grid;gap:6px;margin:12px 0;font-size:14px}.field input,.field textarea{width:100%;border:1px solid #d9dee7;border-radius:9px;padding:12px;font:inherit}.actions{display:flex;gap:10px}.actions>*{flex:1}.secondary{background:#eef1f6;color:#182230}.error{color:#b42318}.success{background:#eaf8ef;padding:14px;border-radius:10px;color:#155b31}
</style></head><body>
<header class="top"><div class="brand" id="company">Katalog</div><div class="live" id="live">● yükleniyor</div></header>
<main class="wrap"><section class="intro"><h1 id="title">Katalog yükleniyor…</h1><p id="description">Beğendiğiniz ürünleri sepetinize ekleyip sipariş talebi oluşturabilirsiniz.</p></section><section class="grid" id="products"><div class="status">Ürünler yükleniyor…</div></section></main>
<button class="cart" id="cartButton" hidden>Sepetim <span id="cartCount">0</span></button>
<div class="modal" id="modal"><section class="sheet" id="sheet"></section></div>
<script>
const KEY=<?=json_encode($catalogKey)?>, API='api.php', CART=new Map(), SESSION_KEY='catalog_session_'+KEY;
let sessionId=localStorage.getItem(SESSION_KEY);if(!sessionId){sessionId=crypto.randomUUID().replaceAll('-','');localStorage.setItem(SESSION_KEY,sessionId)}
let catalog=null,products=[];
async function post(action,data){const r=await fetch(`${API}?action=${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,key:KEY,session_id:sessionId})});const j=await r.json();if(!r.ok)throw Error(j.error||'İşlem tamamlanamadı');return j}
async function load(){if(!KEY){showError('Katalog bağlantısı geçersiz');return}try{const r=await fetch(`${API}?action=catalog&key=${encodeURIComponent(KEY)}`);const j=await r.json();if(!r.ok)throw Error(j.error);catalog=j.catalog;products=j.products;document.title=catalog.title;document.documentElement.style.setProperty('--accent',catalog.catalog_theme_color_hex||'#2359d1');document.getElementById('title').textContent=catalog.title;document.getElementById('description').textContent=catalog.description||'Beğendiğiniz ürünleri sepetinize ekleyip sipariş talebi oluşturabilirsiniz.';document.getElementById('company').textContent=catalog.business_name||'Katalog';render();live(j.active_viewers);await post('activity',{event:'catalog_open'})}catch(e){showError(e.message)}}
function showError(message){document.getElementById('title').textContent=message;document.getElementById('products').innerHTML=''}
function live(n){document.getElementById('live').textContent=`● Şu an ${n} kişi katalogda`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(amount,currency){return `${Number(amount).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} ${currency||catalog?.currency_symbol||'₺'}`}
function render(){const root=document.getElementById('products');if(!products.length){root.innerHTML='<div class="status">Bu katalogda henüz ürün yok.</div>';return}root.innerHTML=products.map(p=>`<article class="card"><img src="${esc(p.image_url||'')}" alt="${esc(p.name)}" loading="lazy" onerror="this.style.visibility='hidden'"><div class="cardbody"><h2>${esc(p.name)}</h2><div class="desc">${esc(p.description||'')}</div><div class="price">${money(p.price,p.currency)}</div><button class="btn" data-add="${esc(p.id)}">Sepete ekle</button></div></article>`).join('');root.querySelectorAll('[data-add]').forEach(button=>button.addEventListener('click',()=>add(button.dataset.add)))}
async function add(productId){const p=products.find(x=>String(x.id)===String(productId));if(!p)return;CART.set(String(p.id),(CART.get(String(p.id))||0)+1);document.getElementById('cartButton').hidden=false;document.getElementById('cartCount').textContent=[...CART.values()].reduce((a,b)=>a+b,0);try{await post('activity',{event:'add_to_cart',product_id:p.id})}catch(e){}}
function openCart(){const sheet=document.getElementById('sheet');const items=[...CART].map(([id,q])=>({p:products.find(x=>String(x.id)===id),q})).filter(x=>x.p);if(!items.length)return;const subtotal=items.reduce((s,x)=>s+Number(x.p.price)*x.q,0),shipping=Number(catalog.shipping_fee||0),currency=catalog.currency_symbol||'₺';sheet.innerHTML=`<h2>Sipariş talebi</h2><div class="rows">${items.map(x=>`<div class="row"><span>${esc(x.p.name)} × ${x.q}</span><b>${money(Number(x.p.price)*x.q,x.p.currency)}</b></div>`).join('')}<div class="row"><span>Ara toplam</span><b>${money(subtotal,currency)}</b></div>${shipping>0?`<div class="row"><span>Kargo</span><b>${money(shipping,currency)}</b></div>`:''}<div class="row"><b>Toplam</b><b>${money(subtotal+shipping,currency)}</b></div></div><form id="orderForm"><label class="field">Adınız soyadınız<input name="name" required maxlength="255" autocomplete="name"></label><label class="field">Telefon<input name="phone" required maxlength="64" type="tel" autocomplete="tel"></label><label class="field">Teslimat adresi<textarea name="address" rows="2" maxlength="2000" autocomplete="street-address"></textarea></label><label class="field">Not (isteğe bağlı)<textarea name="note" rows="2" maxlength="2000"></textarea></label><p class="error" id="err"></p><div class="actions"><button type="button" class="btn secondary" onclick="closeCart()">Kapat</button><button class="btn" type="submit">Sipariş talebi gönder</button></div></form>`;document.getElementById('orderForm').onsubmit=submitOrder;document.getElementById('modal').classList.add('open')}
function closeCart(){document.getElementById('modal').classList.remove('open')}
async function submitOrder(ev){ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const f=new FormData(form),items=[...CART].map(([product_id,quantity])=>({product_id,quantity}));const result=await post('order',{name:f.get('name'),phone:f.get('phone'),address:f.get('address'),note:f.get('note'),items});const sheet=document.getElementById('sheet');let phone=(result.whatsapp_phone||'').replace(/\D/g,'');let wa=phone?`<a class="btn" style="display:block;text-align:center;text-decoration:none;margin-top:12px" target="_blank" rel="noopener" href="https://wa.me/${encodeURIComponent(phone)}?text=${encodeURIComponent('Merhaba, '+result.order_number+' numaralı sipariş talebimi ilettim. Toplam: '+result.total_amount+' '+result.currency)}">WhatsApp ile firmaya yaz</a>`:'';sheet.innerHTML=`<div class="success"><h2>Talebiniz alındı</h2><p>Sipariş numaranız: <b>${esc(result.order_number)}</b></p><p>Toplam: <b>${money(result.total_amount,result.currency)}</b></p><p>Firma sizinle iletişime geçerek ödeme bilgilerini paylaşacak.</p></div>${wa}<button class="btn secondary" style="width:100%;margin-top:12px" onclick="closeCart()">Kataloğa dön</button>`;CART.clear();document.getElementById('cartButton').hidden=true}catch(e){document.getElementById('err').textContent=e.message;button.disabled=false}}
document.getElementById('cartButton').onclick=openCart;document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeCart()});load();setInterval(async()=>{try{await post('activity',{event:'heartbeat'});const r=await fetch(`${API}?action=catalog&key=${encodeURIComponent(KEY)}`),j=await r.json();if(r.ok)live(j.active_viewers)}catch(e){}},20000);
</script></body></html>
